def GROUP(target, spec, scope):
    if type(spec) is dict:
        ret = {}
        for k_spec, v_spec in spec.items():
            k = scope[glom](target, k_spec, scope)
            if k is SKIP:
                continue
            if k is STOP:
                return STOP
            if k not in ret:
                ret[k] = None
            cur_scope = dict(scope)
            cur_scope[ACC_TREE] = scope[ACC_TREE].setdefault(k, {})
            v = scope[glom](target, v_spec, cur_scope)
            if v is STOP:
                continue
            if v is not SKIP:
                ret[k] = v
        return ret
    elif type(spec) is list:
        if len(spec) != 1:
            raise BadSpec('expected list of length 1, got %r' % spec)
        v_spec = spec[0]
        ret = scope[ACC_TREE].setdefault('list', [])
        v = scope[glom](target, v_spec, scope)
        if v is STOP:
            return STOP
        if v is not SKIP:
            ret.append(v)
        return ret
    elif hasattr(spec, 'agg'):
        tree = scope[ACC_TREE]
        return spec.agg(target, tree)
    elif hasattr(spec, 'glomit'):
        return spec.glomit(target, scope)
    else:
        return scope[glom](target, spec, scope)

def glomit(self, target, scope):
    if scope[MODE] is not GROUP:
        raise BadSpec("Limit() only valid in Group mode")
    tree = scope[ACC_TREE]
    if self not in tree:
        tree[self] = [0, {}]
    scope[ACC_TREE] = tree[self][1]
    tree[self][0] += 1
    if tree[self][0] > self.n:
        return STOP
    return scope[glom](target, self.subspec, scope)
